  private m = new Map<number, [number, number]>(); // key -> [value, expiry]
  private heap: [number, number][] = [];            // [expiry, key], min-heap by expiry

  private push(item: [number, number]): void {
    const h = this.heap;
    h.push(item);
    let i = h.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (h[p][0] <= h[i][0]) break;
      [h[p], h[i]] = [h[i], h[p]];
      i = p;
    }
  }

  private pop(): [number, number] {
    const h = this.heap, top = h[0], last = h.pop()!;
    if (h.length) {
      h[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < h.length && h[l][0] < h[m][0]) m = l;
        if (r < h.length && h[r][0] < h[m][0]) m = r;
        if (m === i) break;
        [h[m], h[i]] = [h[i], h[m]];
        i = m;
      }
    }
    return top;
  }

  private purge(now: number): void {
    while (this.heap.length && this.heap[0][0] <= now) {
      const [exp, key] = this.pop();
      const e = this.m.get(key);
      if (e !== undefined && e[1] === exp) this.m.delete(key); // skip stale entries
    }
  }

  set(now: number, key: number, value: number, ttl: number): boolean {
    this.purge(now);
    const alive = this.m.has(key);
    this.m.set(key, [value, now + ttl]);
    this.push([now + ttl, key]);
    return alive;
